 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientRequestObjectSigningAlgAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRequestObjectSigningAlg returns null on a freshly created holder.
     */
    public function testRequestObjectSigningAlgNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRequestObjectSigningAlgAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRequestObjectSigningAlgAssigned());
        $this->assertNull($holder->getRequestObjectSigningAlg());
    }
}
